fix_replacement:
logic [7:0] timer;
always_ff @(posedge clk or negedge rst_n)
  if (!rst_n)      timer <= 8'h0;
  else if (gnt)    timer <= timer + 1;
  else             timer <= 8'h0;
assign force_revoke = (timer > 8'd200);
assign gnt = (last_gnt == 1'b0 && master0_busy && !force_revoke) ? 1'b0 : last_gnt;
